message.content:
{
  "title": "The Gilded Ruin Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party approaches the ruined royal city.",
      "visual_description": "A massive stone archway, half-collapsed and overgrown with thorny vines, marks the entrance to a fallen city; tattered royal banners hang limp in the still air.",
      "characters": ["Riona", "Kael", "Serin"]
    },
    {
      "scene_number": 2,
      "caption": "Townspeople whisper warnings at the market square.",
      "visual_description": "Frightened villagers huddle near a dried-up fountain, their eyes darting toward the palace towers; one woman clutches a child and points fearfully.",
      "characters": ["Riona", "Elder Maris", "Frightened Townspeople"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrols march through the outer ward.",
      "visual_description": "Rows of plate-armored soldiers with crimson crests stomp in unison past broken colonnades, their visors lowered, shields bearing a sunburst emblem.",
      "characters": ["Kael", "Serin", "Crimson Patrol"]
    },
    {
      "scene_number": 4,
      "caption": "The party scouts the forbidden castle gates.",
      "visual_description": "Iron gates rusted shut, their bars entwined with glowing blue ivy; beyond them a courtyard littered with rubble and a single white flagpole.",
      "characters": ["Riona", "Kael", "Serin"]
    },
    {
      "scene_number": 5,
      "caption": "A cursed tower looms over the inner bailey.",
      "visual_description": "A spiral tower of black stone, its windows sealed with greenish crystal, a faint hum emanating from its peak; a raven perches on a broken spire.",
      "characters": ["Serin", "Raven"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a dragon spread through the camp.",
      "visual_description": "Flickering campfire light casts long shadows on a tent wall as a hooded storyteller gestures wildly, a crude dragon drawing scratched into the dirt floor.",
      "characters": ["Kael", "Hooded Storyteller", "Camp Followers"]
    },
    {
      "scene_number": 7,
      "caption": "The party enters the throne room.",
      "visual_description": "Shattered stained glass scatters rainbow light across a cracked marble floor; an empty throne of gilded bone sits on a raised dais, cobwebs veiling the arms.",
      "characters": ["Riona", "Kael", "Serin"]
    },
    {
      "scene_number": 8,
      "caption": "A magic door blocks the lower vaults.",
      "visual_description": "A door of polished obsidian engraved with shifting runes, its surface rippling like water; no handle or lock is visible, only pulsing glyphs.",
      "characters": ["Riona", "Serin"]
    },
    {
      "scene_number": 9,
      "caption": "Kael disarms the rune trap.",
      "visual_description": "Kael crouches before the door, a thin blade tracing the rune lines; sparks fly as a ward flares and fades, the stone groaning open.",
      "characters": ["Kael", "Riona", "Serin"]
    },
    {
      "scene_number": 10,
      "caption": "The rescue target is found in the dungeon.",
      "visual_description": "A dim cell with rusted bars, straw on the floor; a figure in chains lifts their head, face pale but eyes defiant.",
      "characters": ["Riona", "Kael", "Serin", "Prince Aldric"]
    },
    {
      "scene_number": 11,
      "caption": "Alarms sound as the patrol discovers them.",
      "visual_description": "A gong boom echoes through stone corridors; torchlight bounces off armor as soldiers round a corner, swords drawn.",
      "characters": ["Crimson Patrol", "Riona", "Kael", "Serin", "Prince Aldric"]
    },
    {
      "scene_number": 12,
      "caption": "Fight through the armory hall.",
      "visual_description": "Sparks fly from clashing blades amid racks of rusted weapons; a suit of animated armor lurches forward, halberd swinging.",
      "characters": ["Kael", "Serin", "Animated Armor", "Crimson Patrol"]
    },
    {
      "scene_number": 13,
      "caption": "Riona unlocks the sealed treasury door.",
      "visual_description": "A silver disc with spinning concentric rings embedded in a stone wall; Riona twists the rings until they align with a click, dust raining down.",
      "characters": ["Riona", "Prince Aldric"]
    },
    {
      "scene_number": 14,
      "caption": "The party crosses the cursed tower bridge.",
      "visual_description": "A narrow stone bridge high above a mist-filled chasm, its railings carved with weeping faces; the black tower looms at the far end.",
      "characters": ["Riona", "Kael", "Serin", "Prince Aldric"]
    },
    {
      "scene_number": 15,
      "caption": "A spectral guardian rises from the tower gate.",
      "visual_description": "A translucent knight in ancient plate armor, sword wreathed in blue flame, materializes from the stone archway, its eyes empty sockets.",
      "characters": ["Spectral Guardian", "Kael", "Serin"]
    },
    {
      "scene_number": 16,
      "caption": "The dragon is sighted circling above.",
      "visual_description": "A massive winged silhouette passes across the low clouds, scales glinting like embers; a deep roar rattles the broken windows.",
      "characters": ["Riona", "Prince Aldric", "Dragon"]
    },
    {
      "scene_number": 17,
      "caption": "Final escape across the great bridge.",
      "visual_description": "A long stone bridge spanning a river of molten light, its arches crumbling; the party runs as the city crumbles behind them, the dragon diving from above.",
      "characters": ["Riona", "Kael", "Serin", "Prince Aldric", "Dragon"]
    },
    {
      "scene_number": 18,
      "caption": "The party reaches the far side and looks back.",
      "visual_description": "Dawn light breaks over the ruined city, the bridge collapsing into the chasm; the five figures stand on a grassy hill, catching their breath.",
      "characters": ["Riona", "Kael", "Serin", "Prince Aldric"]
    }
  ]
}

